"""Resolve only category names needed by validated records."""

import json


def process(records, categories):
    decoded = {}
    needed = {}
    rows = []
    absent = [-1]
    for raw in records:
        if not isinstance(raw, str):
            continue
        if raw not in decoded:
            decoded[raw] = None
            if not raw.lstrip().startswith("{"):
                continue
            try:
                item = json.loads(raw)
            except json.JSONDecodeError:
                continue
            if not isinstance(item, dict):
                continue
            record_id = item.get("id")
            amount = item.get("amount", 0)
            category = item.get("category", "")
            if not isinstance(record_id, str) or type(amount) is not int or not isinstance(category, str):
                continue
            category = category.strip().casefold()
            if category:
                if category not in needed:
                    needed[category] = [-1]
                position = needed[category]
            else:
                position = absent
            decoded[raw] = (record_id, amount, position)
        row = decoded[raw]
        if row is not None:
            rows.append(row)
    remaining = len(needed)
    if remaining:
        for i, name in enumerate(categories):
            position = needed.get(name)
            if position is not None:
                position[0] = i
                remaining -= 1
                if not remaining:
                    break
    return [{"id": record_id, "amount": amount, "category": position[0]}
            for record_id, amount, position in rows]

