import json


def process(records, categories):
    rows = []
    normalized = {}
    demanded = {"": [-1]}
    for raw in records:
        if not isinstance(raw, str):
            continue
        raw = str.strip(raw, " \t\n\r")
        if raw not in normalized:
            normalized[raw] = None
            if not (raw.startswith("{") and raw.endswith("}")):
                continue
            try:
                record = json.loads(raw)
            except json.JSONDecodeError:
                continue
            if not isinstance(record, dict):
                continue
            record_id = record.get("id")
            amount = record.get("amount", 0)
            category = record.get("category", "")
            if not isinstance(record_id, str) or type(amount) is not int or not isinstance(category, str):
                continue
            category = category.strip().casefold()
            if category not in demanded:
                demanded[category] = [-1]
            normalized[raw] = (record_id, amount, demanded[category])
        row = normalized[raw]
        if row is not None:
            rows.append(row)
    remaining = len(demanded) - 1
    if remaining:
        for index, name in enumerate(categories):
            target = demanded.get(name)
            if target is not None:
                target[0] = index
                remaining -= 1
                if not remaining:
                    break
    return [{"id": row[0], "amount": row[1], "category": row[2][0]} for row in rows]

